mapper.select:
select
, pro.State as state, mn.*, () as spId, ifnull(c11.C_Name, pro.P_Use_Unit) as pUseUnitName from Sec_Bidding_Project mn left join Sec_Procurement_Plan spp on spp.pp_id= mn.pp_id
left join Sec_Bidding_Plan sbp on sbp.Bp_Id=mn.Bp_Id left join SYS_Company c11 on c11.C_Id=pro.P_Use_Unit where mn.Bp_Id=#{bpId}

mapper.sql:

    and mn.is_new = '1'


    and (mn.is_new is null or mn.is_new = '')


    and mn.Te_Id = #{params.teId}


    and mn.State=#{params.state}


    and mn.Bp_Name like concat('%',#{params.bpName},'%')


    and mn.Bp_Create_Uname like concat('%',#{params.bpCreateUname},'%')

and mn.Bp_Id in
(select mn.Bp_Id
from Sec_Bidding_Project mn
left join Pre_Project pro on mn.P_Id=pro.P_Id
left join SYS_Department prod on prod.D_Id=pro.P_Competent_Department
left join SYS_Company c11 on c11.C_Id=pro.P_Use_Unit
${params.authSql}

    and pro.P_Build_Model = #{params.pBuildModel}


    and pro.P_Category = #{params.pCategory}


    
        
            and (pro.P_Build_Model is null or pro.P_Build_Model = '')
        
        
            and pro.P_Build_Model in
            
                #{item}
            
        
    


    and pro.P_Id = #{params.pId}


    and pro.P_Type = #{params.pType}


    
        
            and (pro.P_Type is null or pro.P_Type = '')
        
        
            and pro.P_Type in
            
                #{item}
            
        
    


    and (pro.P_Use_Unit like concat('%',#{params.pUseUnit},'%')
    or c11.C_Name like concat('%',#{params.pUseUnit},'%'))


    
        
            and (pro.P_Use_Unit is null or pro.P_Use_Unit = '' or c11.C_Name is null or c11.C_Name = '')
        
        
            and (pro.P_Use_Unit in
            
                #{item}
            
            or
            c11.C_Name in
            
                #{item}
            )
        
    


    and pro.P_Imp_Company like concat('%',#{params.pImpCompany},'%')


    
        
            and (pro.P_Imp_Company is null or pro.P_Imp_Company = '')
        
        
            and pro.P_Imp_Company in
            
                #{item}
            
        
    


    and pro.P_Name like concat('%',#{params.pName},'%')


    
        
            and (pro.P_Name is null or pro.P_Name = '')
        
        
            and pro.P_Name in
            
                #{item}
            
        
    


    and prod.D_Name like concat('%',#{params.pCompetentDepartmentName},'%')


    
        
            and (pro.D_Name is null or pro.D_Name = '')
        
        
            and pro.D_Name in
            
                #{item}
            
        
    

)

mapper.select:
select si_agg.secMoneys, si_agg.secInfoTotal, si_agg.finishCount, u1.U_Name as bpTendereeName, c2.C_Name as bpCname, case when sbpc.Bpc_Id is not null then 1 else 0 end as hasChange, mn.*, u2.U_Name as responsibleLeaderName, u3.C_ID as bpCreateCid from Sec_Bidding_Plan mn left join SYS_User u1 on u1.U_Id=mn.Bp_Tenderee left join SYS_User u2 on u2.U_Id=mn.Responsible_Leader left join SYS_User u3 on u3.U_Id=mn.Bp_Create_Uid left join SYS_Company c2 on c2.C_Id=mn.Bp_Cid left join ( select sbpc.* from Sec_Bidding_Plan_Change sbpc where sbpc.State != 3 and sbpc.State != 7 ) sbpc on sbpc.Bp_Id=mn.Bp_Id left join ( select sec.Bp_Id, sum(sec.Sec_Money) as secMoneys, count(1) as secInfoTotal, sum( case when sec.Sec_Bidding_Type='05' then (select count(*) from Sec_Price_Resultsf pr where pr.State=7 and pr.Sec_Id=sec.Sec_Id) else case when sec.Sec_Bidding_Type='03' then (select count(*) from Sec_Entrust se where se.State=7 and se.Sec_Id=sec.Sec_Id) else (select count(*) from Sec_Win_Notice wn where wn.Wn_State=7 and wn.Sec_Id=sec.Sec_Id) end end ) as finishCount from Sec_Info sec group by sec.Bp_Id ) si_agg on si_agg.Bp_Id=mn.Bp_Id ${params.mainAuthSql}
order by mn.${params.sortFiled} ${params.sortType}
order by mn.Bp_Create_Time DESC

mapper.sql:
select distinct mn.P_Id, mn.P_Code, mn.P_Name, mn.P_Create_Time, sd.D_Name as pCompetentDepartmentName, (select count(1) from Sec_Info where 1=1
and Sec_Flow_State = #{params.secFlowState}
and Bp_Id in (select Bp_Id from Sec_Bidding_Project where P_Id=mn.P_Id)) as secTotal, (select sum(Sec_Money) from Sec_Info where 1=1
and Sec_Flow_State = #{params.secFlowState}
and Bp_Id in (select Bp_Id from Sec_Bidding_Project where P_Id=mn.P_Id)) as secMoneyTotal, (select Sec_Create_Uname from Sec_Info where 1=1
and Sec_Flow_State = #{params.secFlowState}
and Bp_Id in (select Bp_Id from Sec_Bidding_Project where P_Id=mn.P_Id) limit 1) as secCreateUname from Pre_Project mn left join Sec_Bidding_Project sbp on mn.P_Id=sbp.P_Id left join Sec_Bidding_Plan bp on sbp.Bp_Id=bp.Bp_Id left join Sys_Department sd on sd.D_Id=mn.P_Competent_Department left join Sec_Info sec on sec.Bp_Id=bp.Bp_Id ${params.authSql} and bp.Bp_Id is not null
and mn.Te_Id = #{params.teId}
and sec.Sec_Flow_State = #{params.secFlowState}
order by mn.P_Create_Time desc

mapper.select:
select sbp.P_Id as pId, u1.U_Name as bpTendereeName, c2.C_Name as bpCname, bp.*, u2.U_Name as responsibleLeaderName from Sec_Bidding_Plan bp left join SYS_User u1 on u1.U_Id=bp.Bp_Tenderee left join SYS_Company c2 on c2.C_Id=bp.Bp_Cid left join Sec_Bidding_Project sbp on sbp.Bp_Id=bp.Bp_Id left join Sec_Info sec on bp.Bp_Id=sec.Bp_Id left join SYS_User u2 on u2.U_Id=mn.Responsible_Leader where 1=1
and sec.Sec_Flow_State = #{params.secFlowState}
and sbp.P_Id in
#{pId}

select mn.* from SYS_FileTemplate mn where mn.T_Code in
#{tCode}
and mn.T_Stats = 1

select count(*)
from ${table}
where sec_id = #{secId}
and ${stateKey} = 7
